using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> AuthorizeAsync(int status, string body)
    {
        using var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        await provider.ReceivedAsync();
        return (outcome, provider);
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_with_reference_amount_and_currency()
    {
        var (_, provider) = await AuthorizeAsync(200, """{"status":"approved"}""");

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.ContentType);
        using var json = JsonDocument.Parse(provider.RequestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await AuthorizeAsync(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await AuthorizeAsync(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, _) = await AuthorizeAsync(200, """{"id":"a1","status":"approved","score":0.2}""");

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refused_payment_is_read_as_declined()
    {
        var (outcome, _) = await AuthorizeAsync(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_are_surfaced_rather_than_treated_as_a_decision(int status)
    {
        var error = await Assert.ThrowsAsync<HttpRequestException>(() => AuthorizeAsync(status, """{"error":"x"}"""));

        Assert.Equal((System.Net.HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_surfaced()
    {
        await Assert.ThrowsAnyAsync<JsonException>(() => AuthorizeAsync(200, "<html>oops</html>"));
    }

    [Theory]
    [InlineData("{}")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"outcome":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    public async Task An_answer_without_a_recognised_approval_is_never_read_as_approved(string body)
    {
        var (outcome, _) = await AuthorizeAsync(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }
}
